window.CODE = Object.assign(window.CODE || {}, {"ch25/analyst_team.py":"\"\"\"An agent that writes code and another that runs it, with a person approving every run.\n\nanalyst (writes Python) --> executor (runs it, returns the output) --> analyst (explains) --> ...\n\nSECURITY: code written by a model is untrusted code. This example runs it in a throw-away folder with a\ntimeout and asks YOU first. For anything beyond a demo run it in Docker (snippet at the bottom) so a bad\nscript cannot touch your files, network or keys.\n\nRun:  python analyst_team.py\n\"\"\"\nimport asyncio\nimport tempfile\n\nfrom autogen_agentchat.agents import AssistantAgent, CodeExecutorAgent\nfrom autogen_agentchat.agents import ApprovalRequest, ApprovalResponse\nfrom autogen_agentchat.conditions import MaxMessageTermination, TextMentionTermination\nfrom autogen_agentchat.teams import RoundRobinGroupChat\nfrom autogen_agentchat.ui import Console\nfrom autogen_ext.code_executors.local import LocalCommandLineCodeExecutor\n\nfrom clients import model_client\n\n\ndef approve(request: ApprovalRequest) -> ApprovalResponse:\n    \"\"\"Show the code and wait for a person. Return approved=False to block it.\"\"\"\n    print(\"\\n--- code the agent wants to run ---\\n\" + request.code + \"\\n-----------------------------------\")\n    ok = input(\"Run it? [y/N] \").strip().lower() == \"y\"\n    return ApprovalResponse(approved=ok, reason=\"\" if ok else \"The person declined to run this code.\")\n\n\nasync def main() -> None:\n    with tempfile.TemporaryDirectory() as work_dir:\n        executor = LocalCommandLineCodeExecutor(work_dir=work_dir, timeout=20)   # timeout in seconds\n        analyst = AssistantAgent(\n            \"analyst\", model_client(),\n            system_message=\"You analyse clinic numbers by writing short Python scripts in ```python blocks. Print results. \"\n                           \"Wait for the output, then explain it in one sentence and end with DONE.\",\n        )\n        runner = CodeExecutorAgent(\"runner\", code_executor=executor, approval_func=approve)\n        team = RoundRobinGroupChat([analyst, runner], termination_condition=TextMentionTermination(\"DONE\") | MaxMessageTermination(6))\n        result = await Console(team.run_stream(task=\"Today's OPD bills were Rs 450, 350, 100 and 800. Work out the total and the average.\"))\n        print(\"\\nstopped because:\", result.stop_reason)\n\n\n# Safer: swap the executor for Docker (pip install \"autogen-ext[docker]\"; Docker must be running):\n#   from autogen_ext.code_executors.docker import DockerCommandLineCodeExecutor\n#   async with DockerCommandLineCodeExecutor(work_dir=\"work\", timeout=20) as executor: ...\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch25/clients.py":"\"\"\"One place that creates the model client for every team in this chapter.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\n\nAutoGen needs to KNOW what a model can do (tools? JSON?). For models it does not recognise it falls back to\na cautious default with function_calling=False, and your agents then silently cannot use tools.\nSo for Anthropic we state the capabilities ourselves with model_info.\n\nVersion note: AutoGen 0.7.5's Anthropic client always sends `temperature`, and the anthropic SDK 1.0 and later\nrejects it. So AutoGen needs `anthropic<1` and its own virtual environment (see requirements-autogen.txt).\n\"\"\"\nimport os\n\nfrom autogen_core.models import ChatCompletionClient, ModelInfo\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n\ndef model_client() -> ChatCompletionClient:\n    if os.getenv(\"PROVIDER\", \"openai\").lower() == \"anthropic\":\n        from autogen_ext.models.anthropic import AnthropicChatCompletionClient\n        return AnthropicChatCompletionClient(\n            model=os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\"),\n            max_tokens=600, timeout=30,\n            model_info=ModelInfo(vision=True, function_calling=True, json_output=True,\n                                 family=\"unknown\", structured_output=False),\n        )\n    from autogen_ext.models.openai import OpenAIChatCompletionClient\n    return OpenAIChatCompletionClient(model=os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"), temperature=0, timeout=30)\n","ch25/clinic_tools.py":"\"\"\"The Chapter 9 clinic functions as plain async Python functions.\n\nAutoGen turns any function with type hints and a docstring into a tool: the docstring is what the model reads.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch09\"))\nimport clinic  # noqa: E402\n\n\nasync def get_doctor_schedule(department: str) -> dict:\n    \"\"\"Look up which doctors in a hospital department see patients on which weekdays.\"\"\"\n    return clinic.get_doctor_schedule(department)\n\n\nasync def request_appointment(doctor: str, day: str, patient_name: str) -> dict:\n    \"\"\"Create an appointment REQUEST for staff to approve. It does not confirm a booking.\"\"\"\n    return clinic.request_appointment(doctor, day, patient_name)\n","ch25/requirements-autogen.txt":"# AutoGen 0.7.5 (its last feature release) in its OWN virtual environment:\n#   python -m venv .venv-autogen && source .venv-autogen/bin/activate && pip install -r requirements-autogen.txt\n# Why separate: AutoGen's Anthropic client always sends `temperature`, which the anthropic SDK 1.0+ no longer accepts.\nautogen-agentchat==0.7.5\nautogen-ext[openai,anthropic]==0.7.5\nanthropic<1\npython-dotenv>=1.0\n","ch25/reviewed_reply.py":"\"\"\"A first AutoGen team: a drafter and a safety reviewer take turns until the reviewer says APPROVED.\n\nThis is the reflection pattern from Chapter 11 as a conversation.\n\n    drafter -> reviewer -> (drafter fixes) -> reviewer -> \"APPROVED\" -> stop\n\nRun:  python reviewed_reply.py\n\"\"\"\nimport asyncio\n\nfrom autogen_agentchat.agents import AssistantAgent\nfrom autogen_agentchat.conditions import MaxMessageTermination, TextMentionTermination\nfrom autogen_agentchat.teams import RoundRobinGroupChat\nfrom autogen_agentchat.ui import Console\n\nfrom clients import model_client\nfrom clinic_tools import get_doctor_schedule\n\n\ndef build_team(stop=None) -> RoundRobinGroupChat:\n    drafter = AssistantAgent(\n        \"drafter\", model_client(), tools=[get_doctor_schedule],\n        reflect_on_tool_use=True,       # after a tool runs, the model writes a normal reply from the result\n        system_message=\"You are the City Clinic helpdesk. Look up schedules with your tool, then write a reply of at most \"\n                       \"two sentences. Never give medical advice. If the reviewer lists problems, fix them and reply again.\",\n    )\n    reviewer = AssistantAgent(\n        \"reviewer\", model_client(),\n        system_message=\"You review patient replies. Reject any reply that gives medical advice, or states a doctor or day \"\n                       \"that the schedule tool did not return. If it is fine, answer with exactly APPROVED. \"\n                       \"Otherwise list the problems in one sentence.\",\n    )\n    # Stop on the magic word OR after 8 messages, whichever comes first: never rely on one stop rule.\n    stop = stop or (TextMentionTermination(\"APPROVED\") | MaxMessageTermination(8))\n    return RoundRobinGroupChat([drafter, reviewer], termination_condition=stop)\n\n\nasync def main() -> None:\n    team = build_team()\n    result = await Console(team.run_stream(task=\"Patient asks: which cardiologist is in on Thursday?\"))\n    print(\"\\nstopped because:\", result.stop_reason)\n    await team.reset()          # clears the conversation so the same team object can be reused\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch25/selector_team.py":"\"\"\"SelectorGroupChat: after every message, a model reads the conversation and picks who speaks next.\n\nIt is the supervisor of Chapter 22, but the \"supervisor\" is just a model call with a prompt and no tools.\nYou can replace it with plain code (selector_func) when the order is known.\n\nRun:  python selector_team.py\n\"\"\"\nimport asyncio\n\nfrom autogen_agentchat.agents import AssistantAgent\nfrom autogen_agentchat.conditions import MaxMessageTermination, TextMentionTermination\nfrom autogen_agentchat.teams import SelectorGroupChat\nfrom autogen_agentchat.ui import Console\n\nfrom clients import model_client\nfrom clinic_tools import get_doctor_schedule\n\nFACTS = {\n    \"billing\": \"OPD registration fee Rs 100, valid 7 days for the same doctor. ECG Rs 350. Refunds need billing-desk approval.\",\n    \"insurance\": \"PM-JAY, CGHS and the state scheme are accepted. Planned admissions need pre-authorisation 48 hours ahead.\",\n}\n\n\ndef build_team() -> SelectorGroupChat:\n    scheduling = AssistantAgent(\"scheduling\", model_client(), tools=[get_doctor_schedule], reflect_on_tool_use=True,\n                                description=\"Doctor availability and weekdays. Uses the schedule tool.\",\n                                system_message=\"You are the City Clinic scheduling desk. Use the tool; never guess. One or two sentences.\")\n    billing = AssistantAgent(\"billing\", model_client(),\n                             description=\"Fees, bills and refunds.\",\n                             system_message=f\"You are the City Clinic billing desk. Facts: {FACTS['billing']} One or two sentences.\")\n    insurance = AssistantAgent(\"insurance\", model_client(),\n                               description=\"Insurance schemes and pre-authorisation.\",\n                               system_message=f\"You are the City Clinic insurance desk. Facts: {FACTS['insurance']} One or two sentences.\")\n    closer = AssistantAgent(\"closer\", model_client(),\n                            description=\"Writes the final reply to the patient once every question has been answered.\",\n                            system_message=\"Combine the desks' answers into one short reply for the patient, using only what they said. \"\n                                           \"End with the word DONE.\")\n    return SelectorGroupChat(\n        [scheduling, billing, insurance, closer],\n        model_client=model_client(),                      # the model that picks the next speaker\n        termination_condition=TextMentionTermination(\"DONE\") | MaxMessageTermination(10),\n        allow_repeated_speaker=False,                     # an agent cannot talk twice in a row\n        # selector_func=lambda messages: \"closer\" if ... else None   # plain code instead of the model: None = ask the model\n    )\n\n\nasync def main() -> None:\n    team = build_team()\n    result = await Console(team.run_stream(task=\"Is Dr Rao in on Thursday, and does CGHS cover the OPD visit?\"))\n    print(\"\\nstopped because:\", result.stop_reason)\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch25/state_and_limits.py":"\"\"\"Make a team safe to run for real: hard limits, and saving and restoring its state.\n\nTermination conditions combine with | (either) and & (both). A team with no hard limit can run for ever,\nbecause \"the agents will agree eventually\" is a hope, not a rule.\n\nRun:  python state_and_limits.py\n\"\"\"\nimport asyncio\nimport json\nfrom pathlib import Path\n\nfrom autogen_agentchat.conditions import MaxMessageTermination, TextMentionTermination, TimeoutTermination, TokenUsageTermination\n\nfrom reviewed_reply import build_team\n\nSTATE_FILE = Path(__file__).with_name(\"team_state.json\")\n\n\ndef limits():\n    return (TextMentionTermination(\"APPROVED\")      # the normal way to finish\n            | MaxMessageTermination(8)              # no more than 8 messages\n            | TokenUsageTermination(max_total_token=6000)   # a token budget for the whole run\n            | TimeoutTermination(60))               # and a wall-clock limit in seconds\n\n\nasync def main() -> None:\n    team = build_team(stop=limits())\n    first = await team.run(task=\"Patient asks: which cardiologist is in on Thursday?\")\n    print(\"run 1 stopped because:\", first.stop_reason)\n\n    state = await team.save_state()                 # a plain dict: the conversation so far\n    STATE_FILE.write_text(json.dumps(state))\n    print(\"saved\", len(json.dumps(state)), \"bytes of team state\")\n\n    # Later (even after a restart): build the same team and load the state back.\n    again = build_team(stop=limits())\n    await again.load_state(json.loads(STATE_FILE.read_text()))\n    second = await again.run(task=\"And is the same doctor in on Friday?\")\n    print(\"run 2 stopped because:\", second.stop_reason)\n    print(\"run 2 last reply:\", [m.content for m in second.messages if m.source == \"drafter\"][-1])\n    STATE_FILE.unlink()\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","ch25/swarm_team.py":"\"\"\"Swarm: no selector. Each agent decides for itself by calling a hand-off tool.\n\ntriage --handoff--> scheduling | billing        and any agent can hand off to \"user\" to wait for the patient.\n\nRun:  python swarm_team.py\n\"\"\"\nimport asyncio\n\nfrom autogen_agentchat.agents import AssistantAgent\nfrom autogen_agentchat.base import Handoff\nfrom autogen_agentchat.conditions import HandoffTermination, MaxMessageTermination, TextMentionTermination\nfrom autogen_agentchat.messages import HandoffMessage\nfrom autogen_agentchat.teams import Swarm\nfrom autogen_agentchat.ui import Console\n\nfrom clients import model_client\nfrom clinic_tools import get_doctor_schedule, request_appointment\n\n\ndef build_team() -> Swarm:\n    triage = AssistantAgent(\n        \"triage\", model_client(),\n        handoffs=[\"scheduling\", \"billing\"],          # each name becomes a tool: transfer_to_scheduling, transfer_to_billing\n        system_message=\"You are the City Clinic front desk. Appointments and doctor days: transfer_to_scheduling. \"\n                       \"Bills and fees: transfer_to_billing. Do not answer those yourself. Emergencies: tell the patient to call 108.\",\n    )\n    scheduling = AssistantAgent(\n        \"scheduling\", model_client(), tools=[get_doctor_schedule, request_appointment], reflect_on_tool_use=True,\n        handoffs=[Handoff(target=\"user\", message=\"Ask the patient for the missing detail, then wait.\")],\n        system_message=\"You are the City Clinic scheduling desk. Use the schedule tool. To request an appointment you need the \"\n                       \"patient's full name: if you do not have it, transfer to the user to ask. Say requests need staff approval. \"\n                       \"When the patient is helped, end your reply with DONE.\",\n    )\n    billing = AssistantAgent(\n        \"billing\", model_client(),\n        handoffs=[\"triage\"],\n        system_message=\"You are the City Clinic billing desk. OPD registration fee is Rs 100, valid 7 days for the same doctor. \"\n                       \"ECG is Rs 350. Answer in one sentence and end with DONE. If the question is not about money, transfer back to triage.\",\n    )\n    stop = HandoffTermination(target=\"user\") | TextMentionTermination(\"DONE\") | MaxMessageTermination(12)\n    return Swarm([triage, scheduling, billing], termination_condition=stop)\n\n\nasync def main() -> None:\n    team = build_team()\n    result = await Console(team.run_stream(task=\"I want to see Dr Rao on Thursday.\"))\n    # The swarm paused because an agent handed off to \"user\". Resume with the patient's answer:\n    last = result.messages[-1]\n    if isinstance(last, HandoffMessage) and last.target == \"user\":\n        answer = input(\"Patient: \") or \"Asha Verma\"\n        result = await Console(team.run_stream(task=HandoffMessage(source=\"user\", target=last.source, content=answer)))\n    print(\"\\nstopped because:\", result.stop_reason)\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
